/// helper macro to fixup start/end slice values
macro_rules! ADJUST_INDICES__2 {
    ($start:expr, $end:expr, $len:expr) => {
        loop {
            if ($end) > $len {
                $end = $len;
            } else {
                if ($end) < 0 {
                    let __v: i64 = $len;
                    let __v2: i64 = $end;
                    let __v3: i64 = __v2.wrapping_add(__v);
                    $end = __v3;
                    if ($end) < 0 {
                        $end = 0;
                    }
                }
            }
            if ($start) < 0 {
                let __v4: i64 = $len;
                let __v5: i64 = $start;
                let __v6: i64 = __v5.wrapping_add(__v4);
                $start = __v6;
                if ($start) < 0 {
                    $start = 0;
                }
            }
            if true {
                break;
            }
        }
    };
}

/// helper macro to fixup start/end slice values
