macro_rules! COMPARE__4 {
    ($TYPE1:ty, $data1:expr, $data2:expr, $len:expr) => {{
        loop {
            let mut p1: *mut $TYPE1 = ($data1) as *mut $TYPE1;
            let mut p2: *mut $TYPE1 = ($data2) as *mut $TYPE1;
            let end: *mut $TYPE1 = p1.wrapping_offset(($len) as isize);
            let mut c1: u32 = 0;
            let mut c2: u32 = 0;
            while p1 != end {
                c1 = (unsafe { *p1 }) as u32;
                c2 = (unsafe { *p2 }) as u32;
                if c1 != c2 {
                    return if c1 < c2 { 1i32.wrapping_neg() } else { 1i32 };
                }
                let __v: *mut $TYPE1 = p1;
                p1 = __v.wrapping_offset(1 as isize);
                let __v3: *mut $TYPE1 = p2;
                p2 = __v3.wrapping_offset(1 as isize);
            }
            if true {
                break;
            }
        }
    }};
}

