macro_rules! DECODE_DIRECT {
    ($c:expr) => {
        ($c) <= 127 && ($c) != 43
    };
}

macro_rules! ENCODE_DIRECT {
    ($c:expr, $directO:expr, $directWS:expr) => {
        ($c) < 128
            && ($c) > 0
            && (((unsafe { utf7_category.0[($c) as usize] }) as i32) == 0
                || ($directWS) && ((unsafe { utf7_category.0[($c) as usize] }) as i32) == 2
                || ($directO) && ((unsafe { utf7_category.0[($c) as usize] }) as i32) == 1)
    };
}

