macro_rules! FROM_BASE64 {
    ($c:expr) => {
        if ($c) >= 65 && ($c) <= 90 {
            $c.wrapping_sub(65)
        } else {
            if ($c) >= 97 && ($c) <= 122 {
                $c.wrapping_sub(97).wrapping_add(26)
            } else {
                if ($c) >= 48 && ($c) <= 57 {
                    $c.wrapping_sub(48).wrapping_add(52)
                } else {
                    (if ($c) == 43 { 62i32 } else { 63i32 }) as u32
                }
            }
        }
    };
}

