macro_rules! IS_BASE64 {
    ($c:expr) => {
        ($c) >= 65 && ($c) <= 90
            || ($c) >= 97 && ($c) <= 122
            || ($c) >= 48 && ($c) <= 57
            || ($c) == 43
            || ($c) == 47
    };
}

macro_rules! IS_BASE64__2 {
    ($c:expr) => {
        (($c) as i32) >= 65 && (($c) as i32) <= 90
            || (($c) as i32) >= 97 && (($c) as i32) <= 122
            || (($c) as i32) >= 48 && (($c) as i32) <= 57
            || (($c) as i32) == 43
            || (($c) as i32) == 47
    };
}

