fn asciilib_default_rfind(
    s: *const u8,
    n: i64,
    p: *const u8,
    m: i64,
    maxcount: i64,
    mode: i32,
) -> i64 {
    // create compressed boyer-moore delta 1 table
    let mut mask: u64 = 0;
    let mut i: i64 = 0;
    let mut j: i64 = 0;
    let mlast: i64 = m.wrapping_sub(1);
    let mut skip: i64 = m.wrapping_sub(1);
    let w: i64 = n.wrapping_sub(m);
    // process pattern[0] outside the loop
    STRINGLIB_BLOOM_ADD!(mask, unsafe { *p.wrapping_offset(0 as isize) });
    // process pattern[:0:-1]
    i = mlast;
    while i > 0 {
        STRINGLIB_BLOOM_ADD!(mask, unsafe { *p.wrapping_offset(i as isize) });
        if ((unsafe { *p.wrapping_offset(i as isize) }) as i32)
            == ((unsafe { *p.wrapping_offset(0 as isize) }) as i32)
        {
            skip = i.wrapping_sub(1);
        }
        i = i.wrapping_sub(1);
    }
    i = w;
    while i >= 0 {
        if ((unsafe { *s.wrapping_offset(i as isize) }) as i32)
            == ((unsafe { *p.wrapping_offset(0 as isize) }) as i32)
        {
            // candidate match
            j = mlast;
            while j > 0 {
                if ((unsafe { *s.wrapping_offset(i.wrapping_add(j) as isize) }) as i32)
                    != ((unsafe { *p.wrapping_offset(j as isize) }) as i32)
                {
                    break;
                }
                j = j.wrapping_sub(1);
            }
            if j == 0 {
                // got a match!
                return i;
            }
            // miss: check if previous character is part of pattern
            if i > 0
                && STRINGLIB_BLOOM!(mask, unsafe {
                    *s.wrapping_offset(i.wrapping_sub(1) as isize)
                }) == 0
            {
                i = i.wrapping_sub(m);
            } else {
                i = i.wrapping_sub(skip);
            }
        } else {
            // skip: check if previous character is part of pattern
            if i > 0
                && STRINGLIB_BLOOM!(mask, unsafe {
                    *s.wrapping_offset(i.wrapping_sub(1) as isize)
                }) == 0
            {
                i = i.wrapping_sub(m);
            }
        }
        i = i.wrapping_sub(1);
    }
    1i32.wrapping_neg() as i64
}

fn asciilib_count_char(s: *const u8, n: i64, p0: u8, maxcount: i64) -> i64 {
    let mut count: i64 = 0;
    for i in 0..n {
        if ((unsafe { *s.wrapping_offset(i as isize) }) as i32) == (p0 as i32) {
            count = count.wrapping_add(1);
            if count == maxcount {
                return maxcount;
            }
        }
    }
    count
}

fn asciilib_count_char_no_maxcount(s: *const u8, n: i64, p0: u8) -> i64 {
    let mut count: i64 = 0;
    for i in 0..n {
        if ((unsafe { *s.wrapping_offset(i as isize) }) as i32) == (p0 as i32) {
            count = count.wrapping_add(1);
        }
    }
    count
}

fn asciilib_fastsearch(
    s: *const u8,
    n: i64,
    p: *const u8,
    m: i64,
    maxcount: i64,
    mode: i32,
) -> i64 {
    if n < m || mode == 0 && maxcount == 0 {
        return 1i32.wrapping_neg() as i64;
    }
    // look for special cases
    if m <= 1 {
        if m <= 0 {
            return 1i32.wrapping_neg() as i64;
        }
        // use special case for 1-character strings
        if mode == 1 {
            return asciilib_find_char(s, n, unsafe { *p.wrapping_offset(0 as isize) });
        } else {
            if mode == 2 {
                return asciilib_rfind_char(s, n, unsafe { *p.wrapping_offset(0 as isize) });
            } else {
                if maxcount == 9223372036854775807 {
                    return asciilib_count_char_no_maxcount(s, n, unsafe {
                        *p.wrapping_offset(0 as isize)
                    });
                }
                return asciilib_count_char(
                    s,
                    n,
                    unsafe { *p.wrapping_offset(0 as isize) },
                    maxcount,
                );
            }
        }
    }
    if mode != 2 {
        if n < 2500 || m < 100 && n < 30000 || m < 6 {
            return asciilib_default_find(s, n, p, m, maxcount, mode);
        } else {
            if (m >> 2i32).wrapping_mul(3) < n >> 2i32 {
                // 33% threshold, but don't overflow.
                //
                // For larger problems where the needle isn't a huge
                // percentage of the size of the haystack, the relatively
                // expensive O(m) startup cost of the two-way algorithm
                // will surely pay off.
                if mode == 1 {
                    return asciilib__two_way_find(s, n, p, m);
                } else {
                    return asciilib__two_way_count(s, n, p, m, maxcount);
                }
            } else {
                // To ensure that we have good worst-case behavior,
                // here's an adaptive version of the algorithm, where if
                // we match O(m) characters without any matches of the
                // entire needle, then we predict that the startup cost of
                // the two-way algorithm will probably be worth it.
                return asciilib_adaptive_find(s, n, p, m, maxcount, mode);
            }
        }
    } else {
        // FAST_RSEARCH
        return asciilib_default_rfind(s, n, p, m, maxcount, mode);
    }
}

