fn ucs2lib__lex_search(
    needle: *const u16,
    len_needle: i64,
    return_period: &mut i64,
    invert_alphabet: i32,
) -> i64 {
    // Do a lexicographic search. Essentially this:
    //     >>> max(needle[i:] for i in range(len(needle)+1))
    // Also find the period of the right half.
    let mut max_suffix: i64 = 0;
    let mut candidate: i64 = 1;
    let mut k: i64 = 0;
    // The period of the right half.
    let mut period: i64 = 1;
    while candidate.wrapping_add(k) < len_needle {
        // each loop increases candidate + k + max_suffix
        let a: u16 = unsafe { *needle.wrapping_offset(candidate.wrapping_add(k) as isize) };
        let b: u16 = unsafe { *needle.wrapping_offset(max_suffix.wrapping_add(k) as isize) };
        // check if the suffix at candidate is better than max_suffix
        if (if invert_alphabet != 0 {
            ((b as i32) < (a as i32)) as i32
        } else {
            ((a as i32) < (b as i32)) as i32
        }) != 0
        {
            // Fell short of max_suffix.
            //
            // The next k + 1 characters are non-increasing
            //
            // from candidate, so they won't start a maximal suffix.
            candidate = candidate.wrapping_add(k.wrapping_add(1));
            k = 0;
            // We've ruled out any period smaller than what's
            //
            // been scanned since max_suffix.
            period = candidate.wrapping_sub(max_suffix);
        } else {
            if (a as i32) == (b as i32) {
                if k.wrapping_add(1) != period {
                    // Keep scanning the equal strings
                    k = k.wrapping_add(1);
                } else {
                    // Matched a whole period.
                    //
                    // Start matching the next period.
                    candidate = candidate.wrapping_add(period);
                    k = 0;
                }
            } else {
                // Did better than max_suffix, so replace it.
                max_suffix = candidate;
                candidate = candidate.wrapping_add(1);
                k = 0;
                period = 1;
            }
        }
    }
    unsafe {
        *(return_period as *mut i64) = period;
    }
    max_suffix
}

fn ucs2lib__factorize(needle: *const u16, len_needle: i64, return_period: *mut i64) -> i64 {
    // Do a "critical factorization", making it so that:
    // >>> needle = (left := needle[:cut]) + (right := needle[cut:])
    // where the "local period" of the cut is maximal.
    //
    // The local period of the cut is the minimal length of a string w
    // such that (left endswith w or w endswith left)
    // and (right startswith w or w startswith right).
    //
    // The Critical Factorization Theorem says that this maximal local
    // period is the global period of the string.
    //
    // Crochemore and Perrin (1991) show that this cut can be computed
    // as the later of two cuts: one that gives a lexicographically
    // maximal right half, and one that gives the same with the
    // with respect to a reversed alphabet-ordering.
    //
    // This is what we want to happen:
    //     >>> x = "GCAGAGAG"
    //     >>> cut, period = factorize(x)
    //     >>> x[:cut], (right := x[cut:])
    //     ('GC', 'AGAGAG')
    //     >>> period  # right half period
    //     2
    //     >>> right[period:] == right[:-period]
    //     True
    //
    // This is how the local period lines up in the above example:
    //          GC | AGAGAG
    //     AGAGAGC = AGAGAGC
    // The length of this minimal repetition is 7, which is indeed the
    // period of the original string.
    let mut cut1: i64 = 0;
    let mut period1: i64 = 0;
    let mut cut2: i64 = 0;
    let mut period2: i64 = 0;
    let mut cut: i64 = 0;
    let mut period: i64 = 0;
    cut1 = ucs2lib__lex_search(
        needle,
        len_needle,
        unsafe { &mut (*core::ptr::addr_of_mut!(period1)) },
        0i32,
    );
    cut2 = ucs2lib__lex_search(
        needle,
        len_needle,
        unsafe { &mut (*core::ptr::addr_of_mut!(period2)) },
        1i32,
    );
    // Take the later cut.
    if cut1 > cut2 {
        period = period1;
        cut = cut1;
    } else {
        period = period2;
        cut = cut2;
    }
    unsafe {
        *return_period = period;
    }
    cut
}

